import unittest
from unittest.mock import patch
import download_universe as d

class ArchiveTests(unittest.TestCase):
    def row(self):
        return dict(instrument_name='BTC-4SEP22-16000-C',kind='option',base_currency='BTC',settlement_currency='BTC',quote_currency='BTC',option_type='call',strike=16000,creation_timestamp=1662105660000,expiration_timestamp=1662278400000)
    def wrapper(self):
        return dict(url=d.BULK,params=dict(currency='BTC',kind='option',expired='true'),http_status=200,response=dict(testnet=False,result=[self.row()]))
    def test_archive_keeps_inactive_and_untraded_contracts(self):
        wrapper=self.wrapper();wrapper['response']['result'][0]['is_active']=False
        self.assertEqual(len(d.validate(wrapper,'BTC')),1)
    def test_wrong_source_product_and_duplicate_rejected(self):
        wrapper=self.wrapper();wrapper['url']='https://example.com/get_instruments'
        with self.assertRaises(ValueError):d.validate(wrapper,'BTC')
        wrapper=self.wrapper();wrapper['response']['result'][0]['quote_currency']='USD'
        with self.assertRaises(ValueError):d.validate(wrapper,'BTC')
        wrapper=self.wrapper();wrapper['response']['result'].append(self.row())
        with self.assertRaises(ValueError):d.validate(wrapper,'BTC')
    def test_expiry_and_creation_boundaries(self):
        row=self.row();row['creation_timestamp']=row['expiration_timestamp']
        with self.assertRaises(ValueError):d.identity(row,'BTC')
        row=self.row();row['expiration_timestamp']-=3600000
        with self.assertRaises(ValueError):d.identity(row,'BTC')
        self.assertEqual(d.identity(row,'BTC',strict_expiry=False).hour,8)
    def test_zero_budget_never_calls_network(self):
        with patch.object(d.requests,'get') as get:
            self.assertIsNone(d.Budget(0).fetch(d.BULK,{},None));get.assert_not_called()
    def test_access_denial_blocks_further_requests(self):
        class Response:
            status_code=429
            def __enter__(self):return self
            def __exit__(self,*_):pass
            def iter_content(self,*_):yield b'{"error":{"code":10028}}'
        with patch.object(d.requests,'get',return_value=Response()) as get,patch.object(d,'atomic'):
            budget=d.Budget(100,interval=0);budget.fetch(d.BULK,{},None)
            self.assertIsNone(budget.fetch(d.BULK,{},None));self.assertEqual(get.call_count,1)
if __name__=='__main__':unittest.main()
